commands.command:
cat > /etc/nginx/conf.d/https-8443.conf <<'EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name node1;

    ssl_certificate     /etc/nginx/tls/server.crt;
    ssl_certificate_key /etc/nginx/tls/server.key;

    location / {
        return 200 "ok\n";
        add_header Content-Type text/plain;
    }
}
EOF
cat /etc/nginx/conf.d/https-8443.conf

